        case Team::None: id = 0; return true;
        case Team::Red: id = 0xbb03; return true;
        case Team::Blue: id = 0xf630; return true;
        case Team::Green: id = 0x6e0f; return true;
        case Team::Gold: id = 0xda27; return true;
